/* -------------------------------------------------------------------------
   Typography — ATOM/academy language

   Type scale lives in token CSS custom properties (packages/tokens).
   Fluid sizing is handled by scaling.css via root --size-font; rem values
   scale proportionally.

   Families:
     --font-family-sans     Inter Tight (UI / headings)
     --font-family-display  Grift (hero / display)
     --font-family-mono     Interval
     --font-family-scribble Gantol
   ------------------------------------------------------------------------- */

body {
  font-family: var(--font-family-sans);
  font-size: var(--size-font);
  font-weight: var(--font-weight-regular);
  line-height: var(--line-height-base);
  color: var(--foreground, currentColor);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* --- Display (Grift) --- */

.display,
.display-xl {
  font-family: var(--font-family-display);
  font-size: var(--font-size-6xl);
  line-height: var(--line-height-6xl);
  font-weight: var(--font-weight-regular);
  letter-spacing: var(--letter-spacing-tighter);
  letter-spacing: var(--letter-spacing-tight);
}

.display-lg {
  font-family: var(--font-family-display);
  font-size: var(--font-size-5xl);
  line-height: var(--line-height-5xl);
  font-weight: var(--font-weight-regular);
  letter-spacing: var(--letter-spacing-tighter);
  letter-spacing: var(--letter-spacing-tight);
}

/* --- Headings (Inter Tight / sans) --- */

.h1,
.h2 {
  /* Grift: la voz de la marca vive en los titulos mayores. h3-h6 quedan en
     sans porque son estructura densa, donde la legibilidad manda. */
  font-family: var(--font-family-display);
  letter-spacing: var(--letter-spacing-tight);
}

.h3,
.h4,
.h5,
.h6 {
  font-family: var(--font-family-sans);
  letter-spacing: var(--letter-spacing-snug);
}

.h1 {
  font-size: var(--font-size-4xl);
  line-height: var(--line-height-4xl);
  font-weight: var(--font-weight-bold);
}

.h2 {
  font-size: var(--font-size-3xl);
  line-height: var(--line-height-3xl);
  font-weight: var(--font-weight-semibold);
}

.h3 {
  font-size: var(--font-size-2xl);
  line-height: var(--line-height-2xl);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--letter-spacing-normal);
}

.h4 {
  font-size: var(--font-size-xl);
  line-height: var(--line-height-xl);
  font-weight: var(--font-weight-medium);
  letter-spacing: var(--letter-spacing-normal);
}

.h5 {
  font-size: var(--font-size-lg);
  line-height: var(--line-height-lg);
  font-weight: var(--font-weight-medium);
  letter-spacing: var(--letter-spacing-normal);
}

.h6 {
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--letter-spacing-normal);
}

/* --- Body --- */

.body-lg {
  font-size: var(--font-size-lg);
  line-height: var(--line-height-lg);
}

.body {
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
}

.body-sm {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
}

/* --- Small text --- */

.caption {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
  color: var(--muted-foreground, currentColor);
}

.label {
  font-size: var(--font-size-xs);
  line-height: var(--line-height-xs);
  font-weight: var(--font-weight-medium);
  letter-spacing: var(--letter-spacing-wide);
  text-transform: uppercase;
}

/* --- Family utilities --- */

.mono {
  font-family: var(--font-family-mono);
}

.scribble {
  font-family: var(--font-family-scribble);
}

/* --- Semantic variants --- */

.lead {
  font-size: var(--font-size-lg);
  line-height: var(--line-height-lg);
  color: var(--muted-foreground);
}

.large {
  font-size: var(--font-size-lg);
  line-height: var(--line-height-lg);
  font-weight: var(--font-weight-semibold);
}

.small {
  font-size: var(--font-size-sm);
  line-height: 1;
  font-weight: var(--font-weight-medium);
}

.muted {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
  color: var(--muted-foreground);
}

/* --- Blockquote --- */

.blockquote {
  border-left: var(--stroke-medium) solid var(--border);
  padding-left: var(--spacing-6);
  font-style: italic;
  color: var(--foreground);
}

/* --- List --- */

.list {
  list-style-type: disc;
  margin-left: var(--spacing-6);
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
}

.list > li + li {
  margin-top: var(--spacing-2);
}

/* --- Code --- */

.code {
  font-family: var(--font-family-mono);
  font-size: 0.875em;
}

.code-inline {
  font-family: var(--font-family-mono);
  font-size: 0.875em;
  font-weight: var(--font-weight-semibold);
  background-color: var(--muted);
  border-radius: var(--radius-sm);
  padding: 0.2em 0.4em;
}

/* Eyebrow / overline — etiqueta tecnica de seccion (patron ATOM) */
.eyebrow {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-regular);
  text-transform: uppercase;
  letter-spacing: var(--letter-spacing-wider);
}

/* -------------------------------------------------------------------------
   Fluid Scaling System

   Scales typography and layout proportionally to the viewport.
   Base unit (--size-unit) matches the body font-size from design.
   All rem-based values scale automatically through the root font-size.

   This is the ONLY place where viewport breakpoints are defined.
   Breakpoints are not design tokens — @media queries cannot consume
   CSS custom properties (spec limitation), and responsive behavior
   is a CSS concern, not a token value. Tokens define WHAT sizes exist;
   this file defines HOW they adapt to the viewport.

   Usage:
     body { font-size: var(--size-font); }
     .container { max-width: var(--size-container); }
     .container-md { max-width: calc(var(--size-container) * 0.85); }
     .container-sm { max-width: calc(var(--size-container) * 0.7); }

   Type scale: see tokens/primitives/typography.json (ATOM rem scale)
   ------------------------------------------------------------------------- */


/* ---- Breakpoint reference (for component @media queries) ----
   desktop:          >= 992px   (default)
   tablet:           768–991px
   mobile-landscape:  480–767px
   mobile-portrait:   320–479px
   --------------------------------------------------------------- */


/* Desktop (default) */
:root {
  --size-unit: 16;
  --size-container-ideal: 1440;
  --size-container-min: 992px;
  --size-container-max: 1920px;
  --size-container: clamp(var(--size-container-min), 100vw, var(--size-container-max));
  --size-font: calc(var(--size-container) / (var(--size-container-ideal) / var(--size-unit)));
  /* 1 "design pixel", fluido: la unidad que consumen spacing/font-size/radius
     (emitidos como calc(N * var(--u)) desde tokens). Absoluta -> inmune al
     font-size local, a diferencia de em. */
  --u: calc(var(--size-font) / 16);
  /* Margen LATERAL del contenido — eje distinto al ritmo vertical de seccion.
     Patron ATOM: 30px desktop, 10px bajo 991 (casi full-bleed en movil). */
  --container-padding: calc(30 * var(--u));
  /* Optional content max (academy often uses ~1280) — evaluate vs ideal in PR */
  --size-container-content: calc(1280 * var(--u)); /* fluido: crece con el sistema */
}

/* Tablet — tighten section padding (ATOM media overrides) */
@media screen and (max-width: 991px) {
  :root {
    --size-container-ideal: 834;
    --size-container-min: 768px;
    --size-container-max: 991px;
    --container-padding: calc(10 * var(--u));
    /* Tablet: cada alias baja UN paso exacto de la escala (÷1.25) */
    --section-padding-xxl: calc(156.25 * var(--u));
    --section-padding-xl: calc(125 * var(--u));
    --section-padding-l: calc(100 * var(--u));
    --section-padding-m: calc(80 * var(--u));
    --section-padding-s: calc(64 * var(--u));
  }
}

/* Mobile Landscape */
@media screen and (max-width: 767px) {
  :root {
    --size-container-ideal: 550;
    --size-container-min: 480px;
    --size-container-max: 767px;
    /* Mobile landscape: dos pasos */
    --section-padding-xxl: calc(125 * var(--u));
    --section-padding-xl: calc(100 * var(--u));
    --section-padding-l: calc(80 * var(--u));
    --section-padding-m: calc(64 * var(--u));
    --section-padding-s: calc(51.2 * var(--u));
  }
}

/* Mobile Portrait */
@media screen and (max-width: 479px) {
  :root {
    --size-container-ideal: 390;
    --size-container-min: 320px;
    --size-container-max: 479px;
    /* Mobile portrait: tres pasos */
    --section-padding-xxl: calc(100 * var(--u));
    --section-padding-xl: calc(80 * var(--u));
    --section-padding-l: calc(64 * var(--u));
    --section-padding-m: calc(51.2 * var(--u));
    --section-padding-s: calc(40.96 * var(--u));
  }
}

/* Layout helpers */
.container {
  width: 100%;
  max-width: var(--size-container-content, var(--size-container));
  margin-inline: auto;
  padding-inline: var(--container-padding, 1.875rem);
}

.container-md {
  max-width: calc(var(--size-container-content, var(--size-container)) * 0.85);
}

.container-sm {
  max-width: calc(var(--size-container-content, var(--size-container)) * 0.7);
}

/* -------------------------------------------------------------------------
   Focus Ring — single source of truth

   All interactive components use this pattern.
   Normal: outline via --ring token
   Error:  destructive ring via --destructive / coral
   ------------------------------------------------------------------------- */

:root {
  --focus-ring-color: rgba(161, 161, 161, 0.7);
  --focus-ring-width: 2px;
  --focus-ring-error-color: var(--destructive);
}

[data-theme="dark"] {
  --focus-ring-color: rgba(161, 161, 161, 0.5);
}

