  line-height: 1.05;
  font-weight: 400;
  letter-spacing: -0.03em;
  letter-spacing: -0.02em;
}

.display-lg {
  font-family: 'grift', 'inter tight', georgia, serif;
  font-size: 61.04px;
  line-height: 1.1;
  font-weight: 400;
  letter-spacing: -0.03em;
  letter-spacing: -0.02em;
}

