.code {
  font-family: 'interval', ui-monospace, 'cascadia code', monospace;
  font-size: 0.875em;
}

.code-inline {
  font-family: 'interval', ui-monospace, 'cascadia code', monospace;
  font-size: 0.875em;
  font-weight: 600;
  background-color: #f5f5f5;
  border-radius: 4px;
  padding: 0.2em 0.4em;
}

